SourceCode.Declaration:
/// <summary>
/// Claims or releases one line, in a process running in LineClaim mode. Shared across receiving
/// and both transfer directions - see HSMobileOpsLineClaim, which is equally generic.
/// </summary>
[DataContractAttribute]
class HSMobileOpsClaimRequest
{
    DataAreaId dataAreaId;
    str        sourceId;
    LineNum    lineNumber;
    str        userName;
    str        displayName;
    str        deviceId;

}

Method.Source:
[DataMemberAttribute('DataAreaId')]
public DataAreaId parmDataAreaId(DataAreaId _value = dataAreaId)
{
    dataAreaId = _value;
    return dataAreaId;
}

/// <summary>
/// Purchase order or transfer order number, matching whichever service operation this
/// request is sent to.
/// </summary>
[DataMemberAttribute('SourceId')]
public str parmSourceId(str _value = sourceId)
{
    sourceId = _value;
    return sourceId;
}

[DataMemberAttribute('LineNumber')]
public LineNum parmLineNumber(LineNum _value = lineNumber)
{
    lineNumber = _value;
    return lineNumber;
}

[DataMemberAttribute('UserName')]
public str parmUserName(str _value = userName)
{
    userName = _value;
    return userName;
}

/// <summary>
/// Not looked up server-side. The worker's display name lives in HSMobileOpsUser, but
/// re-selecting it on every claim to save one field on the request is a trade the read path
/// already made the other way - see HSMobileOpsPurchLineContract.ClaimedByDisplayName,
/// which exists purely so a second worker's screen can show a name without its own lookup.
/// </summary>
[DataMemberAttribute('DisplayName')]
public str parmDisplayName(str _value = displayName)
{
    displayName = _value;
    return displayName;
}

[DataMemberAttribute('DeviceId')]
public str parmDeviceId(str _value = deviceId)
{
    deviceId = _value;
    return deviceId;
}
